import {booking, equivalent} from "../common/request.mjs";

/** Studio admission uses its tenant allocation without changing other desks. */
export function bookStudio(ledger, input, catalog = ledger.catalog) {
  const request = booking(input);
  const previous = ledger.inspect(request.id);
  // Identity checks precede admission, including for cancelled reservations.
  if (previous) {
    if (!equivalent(previous, request)) {
      return {status: "conflict", id: request.id};
    }
    return {status: previous.active ? "replay" : "cancelled", id: request.id};
  }
  const cap = catalog.studios.get(request.tenant) ?? catalog.default;
  const used = ledger.usage(request.tenant, request.day);
  if (used + request.units > cap) {
    return {status: "full", id: request.id, remaining: Math.max(0, cap - used)};
  }
  ledger.post(request);
  return {status: "booked", id: request.id, remaining: cap - used - request.units};
}

export function renewStudio(ledger, operation, catalog = ledger.catalog) {
  const previous = ledger.inspect(operation.previous);
  if (!previous || !previous.active) {
    return {status: "missing", id: operation.previous};
  }
  return bookStudio(ledger, {
    id: operation.id,
    day: operation.day,
    tenant: previous.tenant,
    units: operation.units ?? previous.units
  }, catalog);
}
