import {planner} from "./replay.mjs";

const catalog = {default: 5, studios: new Map([["orchid", 8], ["iris", 3]])};
const request = {service:"studio", action:"book", id:"first", tenant:"orchid",
                 day:"2025-04-02", units:7};

 test("Studio allocations preserve identity, cancellation and tenant/day accounting", () => {
  const dispatch = planner(catalog);
  assert.deepEqual(dispatch(request), {status:"booked", id:"first", remaining:1});
  assert.deepEqual(dispatch(request), {status:"replay", id:"first"});
  assert.equal(dispatch({...request, units:8}).status, "conflict");
  assert.deepEqual(dispatch({...request, id:"overflow", units:2}),
                   {status:"full", id:"overflow", remaining:1});
  assert.equal(dispatch({...request, id:"last", units:1}).status, "booked");
  assert.deepEqual(dispatch({service:"studio", action:"usage", tenant:"orchid", day:request.day}),
                   {units:8});
  assert.equal(dispatch({...request, id:"another-day", day:"2025-04-03", units:8}).status, "booked");
  assert.equal(dispatch({...request, id:"unlisted", tenant:"rose", units:5}).status, "booked");
  assert.deepEqual(dispatch({...request, id:"fallback-full", tenant:"rose", units:1}),
                   {status:"full", id:"fallback-full", remaining:0});
  assert.equal(dispatch({...request, id:"low-cap", tenant:"iris", units:4}).status, "full");
  assert.equal(dispatch({...request, id:"low-cap", tenant:"iris", units:3}).status, "booked");
  assert.equal(dispatch({service:"studio", action:"cancel", id:"first"}).status, "cancelled");
  assert.equal(dispatch({service:"studio", action:"cancel", id:"first"}).status, "replay");
  assert.equal(dispatch(request).status, "cancelled");
  assert.equal(dispatch({...request, units:8}).status, "conflict");
  assert.equal(dispatch({...request, id:"replacement"}).status, "booked");
  const summary = dispatch({service:"studio", action:"summary"});
  assert.equal(summary.events.filter(event => event.id === "first").length, 2);
  assert.equal(summary.occupied.some(row => row.id === "first"), false);
});

test("Studio renewals inherit the tenant and share Studio admission", () => {
  const dispatch = planner(catalog);
  dispatch(request);
  const renewal = {service:"studio", action:"renew", previous:"first", id:"next",
                   day:"2025-05-02", tenant:"iris"};
  assert.deepEqual(dispatch(renewal), {status:"booked", id:"next", remaining:1});
  assert.equal(dispatch({...renewal, units:7}).status, "replay");
  assert.equal(dispatch({...renewal, units:8}).status, "conflict");
  assert.deepEqual(dispatch({...renewal, id:"too-many", units:2}),
                   {status:"full", id:"too-many", remaining:1});
  assert.equal(dispatch({...renewal, id:"top-up", units:1}).status, "booked");
  assert.equal(dispatch({service:"studio", action:"lookup", id:"next"}).tenant, "orchid");
  dispatch({service:"studio", action:"cancel", id:"next"});
  assert.equal(dispatch(renewal).status, "cancelled");
  dispatch({service:"studio", action:"cancel", id:"first"});
  assert.deepEqual(dispatch(renewal), {status:"missing", id:"first"});
  assert.deepEqual(dispatch({...renewal, previous:"absent"}), {status:"missing", id:"absent"});

  dispatch({...request, id:"fallback", tenant:"rose", units:5});
  assert.equal(dispatch({...renewal, previous:"fallback", id:"fallback-renewed"}).status, "booked");
  assert.equal(dispatch({...renewal, previous:"fallback", id:"fallback-full", units:1}).status, "full");
});

test("imports count toward Studio quotas while Archive retains the catalog default", () => {
  const dispatch = planner(catalog);
  assert.equal(dispatch({...request, action:"import", units:10}).status, "imported");
  assert.equal(dispatch({...request, units:10}).status, "replay");
