    {service:"studio", action:"renew", previous:"prior", id:"cancelled", day:"2025-04-03"},
    {service:"studio", action:"cancel", id:"cancelled"},
    {service:"studio", action:"book", tenant:"iris", id:"iris", day:"2025-04-02", units:4},
    {service:"archive", action:"book", tenant:"orchid", id:"archive", day:"2025-04-02", units:2}
  ]
};
const expected = [
  {service:"studio", tenant:"orchid", day:"2025-04-02", edition:"orchid-quota", cap:8, used:7, available:1},
  {service:"studio", tenant:"orchid", day:"2025-04-03", edition:"orchid-quota", cap:8, used:0, available:8}
];
const original = [
  {service:"archive", tenant:"orchid", day:"2025-04-02", edition:"signed-spring", cap:5, used:1, available:4},
  {service:"studio", tenant:"orchid", day:"2025-04-01", edition:"signed-spring", cap:5, used:2, available:3},
  {service:"studio", tenant:"iris", day:"2025-04-03", edition:"signed-spring", cap:5, used:4, available:1},
  {service:"studio", tenant:"orchid", day:"2025-04-04", edition:"signed-spring", cap:5, used:3, available:2}
];

function files(t, feed = source, rows = original) {
  const dir = mkdtempSync(join(tmpdir(), "diary-publish-"));
  t.after(() => rmSync(dir, {recursive:true, force:true}));
  const input = join(dir, "feed.json");
  const diary = join(dir, "diary.json");
  writeFileSync(input, JSON.stringify(feed));
  writeFileSync(diary, JSON.stringify(rows));
  const cli = fileURLToPath(new URL("./utilization.mjs", import.meta.url));
  const run = (command = "publish-calendar") => execFileSync(process.execPath, [cli, command, input, diary],
                                                             {encoding:"utf8", stdio:"pipe"});
  return {input, diary, run};
}

test("publication projects the entire replay before selecting inclusive audience cells", () => {
  assert.deepEqual(projectPublication(source, catalog), expected);
  const full = projectCalendar(source, catalog);
  assert.equal(full.length, 12);
  assert.equal(full.find(row => row.service === "studio" && row.tenant === "iris" && row.day === "2025-04-02").used, 4);
  assert.equal(full.find(row => row.service === "archive" && row.day === "2025-04-02").cap, 5);
  assert.deepEqual(projectPublication({...source, window:{...source.window, through:"2025-04-02"}}, catalog),
                   [expected[0]]);
});

test("publish-calendar preserves other editions, replaces matching cells and is byte-idempotent", t => {
  const stale = {...expected[0], edition:"old", used:1, available:7};
  const {diary, run} = files(t, source, [...original, stale]);
  assert.deepEqual(JSON.parse(run()), {edition:"orchid-quota", rows:2});
  const once = readFileSync(diary, "utf8");
  assert.deepEqual(JSON.parse(once), [...original, ...expected]);
  run();
  assert.equal(readFileSync(diary, "utf8"), once);
});

test("preview and rebuild still cover the full feed", t => {
  const {diary, run} = files(t);
  const before = readFileSync(diary, "utf8");
  assert.equal(JSON.parse(run("preview-calendar")).length, 12);
  assert.equal(readFileSync(diary, "utf8"), before);
  assert.deepEqual(JSON.parse(run("rebuild-calendar")), {edition:"orchid-quota", rows:12});
  assert.equal(JSON.parse(readFileSync(diary, "utf8")).length, 12);
});

test("bad publication windows and duplicate diaries fail without changing the diary", t => {
  for (const window of [undefined, {...source.window, service:"other"}, {...source.window, tenant:"?"},
                        {...source.window, from:"2025-02-30"}, {...source.window, through:"2025-04-01"}]) {
